/**
 * Map artwork and world-space bounds, vendored from tarkov.dev's frontend.
 *
 * GENERATED by scripts/make-map-art.ts — run `npm run mapart` to refresh.
 * Source: the-hideout/tarkov-dev, src/data/maps.json.
 *
 * Vendored rather than fetched at runtime: it is a file in an application repo
 * with no versioning guarantee, so a rename upstream would silently empty the
 * map view. Stale beats broken.
 *
 * Coordinates are RAW GAME WORLD UNITS, which is what makes this usable.
 * Verified against the live API: the Customs "Old Gas" label sits at
 * (331, -173) and the Old Gas Station extract reports world (309, -174). So
 * objective positions plot straight against these bounds with no transform —
 * the "transform" array upstream is for aligning raster tile pyramids.
 *
 * "rotation" orients the artwork so north reads up. It is applied to the image
 * and the markers together, so it cannot misalign them; it only decides which
 * way the map faces on screen. It disagrees with the API's
 * coordinateToCardinalRotation on Reserve and The Labyrinth — this is the value
 * that matches this artwork.
 *
 * "svg" is null for maps published only as raster tile pyramids (The Lab, The
 * Labyrinth). Those render no background today.
 */
export interface MapLabel {
  x: number
  z: number
  text: string
}

/**
 * A height band plus the building footprints it applies within.
 *
 * Height alone is not enough: on Customs anything above y=5.7 would count as
 * second floor, which swept 82 outdoor objectives onto the wrong storey. An
 * objective belongs to a floor only if it is inside one of these boxes AND
 * within the height band.
 */
export interface MapExtent {
  height: [number, number]
  /** [x1, z1, x2, z2] corners; empty means the band applies map-wide. */
  boxes: [number, number, number, number][]
}

/** An alternate floor: an SVG group to swap in, and where it applies. */
export interface MapFloor {
  name: string
  /** id of the <g> inside the SVG. */
  group: string
  /**
   * Drawn alongside the ground floor by default rather than instead of it.
   * Interchange's mall interior is a layer, so hiding it leaves only the
   * outdoor ring — and every label sits over a storey that isn't shown.
   */
  defaultOn: boolean
  extents: MapExtent[]
}

export interface MapArt {
  /** [[maxX, minZ], [minX, maxZ]] in world units. */
  bounds: [[number, number], [number, number]]
  /** Degrees; applied to image and markers together. */
  rotation: number
  /** Null when the map has no SVG published. */
  svg: string | null
  /**
   * World rectangle the ARTWORK covers, when it differs from `bounds`.
   * Reserve's SVG spans a taller slice of the world than its marker bounds do,
   * so drawing the image across `bounds` shifts the whole map against the
   * markers plotted on it. Null means the two are the same.
   */
  svgBounds: [[number, number], [number, number]] | null
  /**
   * The SVG group shown by default. Every other floor group is hidden — the
   * artwork stacks all levels in one file, so without this Factory renders its
   * basement over its ground floor.
   */
  baseGroup: string | null
  floors: MapFloor[]
  labels: MapLabel[]
}

